import pandas as pd

def most_common_course_pairs(enrollments: pd.DataFrame) -> pd.DataFrame:
    merged = enrollments.merge(enrollments, on='student_id', suffixes=('_1', '_2'))
    pairs = merged[merged['course_id_1'] < merged['course_id_2']]
    grouped = pairs.groupby(['course_id_1', 'course_id_2'])['student_id'].nunique().reset_index()
    grouped.columns = ['course1_id', 'course2_id', 'pair_count']
    if grouped.empty:
        return pd.DataFrame(columns=['course1_id', 'course2_id', 'pair_count'])
    max_count = grouped['pair_count'].max()
    res = grouped[grouped['pair_count'] == max_count]
    return res.sort_values(by=['course1_id', 'course2_id'])
